  1→const express = require('express');
  2→const fs = require('fs');
  3→const path = require('path');
  4→const os = require('os');
  5→const matter = require('gray-matter');
  6→
  7→const app = express();
  8→app.use(express.json({ limit: '5mb' }));
  9→// Serve built React frontend, fallback to legacy public/
 10→const distPath = path.join(__dirname, '..', 'public-dist');
 11→const legacyPath = path.join(__dirname, '..', 'public');
 12→const staticPath = fs.existsSync(distPath) ? distPath : legacyPath;
 13→app.use(express.static(staticPath));
 14→
 15→const HOME = os.homedir();
 16→const CLAUDE_DIR = path.join(HOME, '.claude');
 17→const CONFIG_PATH = path.join(__dirname, '..', 'config.json');
 18→const HISTORY_PATH = path.join(__dirname, '..', 'chat-history.json');
 19→const ORCHESTRATIONS_PATH = path.join(__dirname, '..', 'orchestrations.json');
 20→
 21→// --- Security: Name & Path Validation ---
 22→function isValidName(name) {
 23→  return /^[a-zA-Z0-9_-]+$/.test(name) && !name.includes('..');
 24→}
 25→
 26→function validateName(req, res, next) {
 27→  if (!isValidName(req.params.name)) {
 28→    return res.status(400).json({ error: 'Invalid name. Only letters, numbers, hyphens and underscores allowed.' });
 29→  }
 30→  next();
 31→}
 32→
 33→function resolveProjectPath(id) {
 34→  try {
 35→    return Buffer.from(id, 'base64url').toString();
 36→  } catch {
 37→    return null;
 38→  }
 39→}
 40→
 41→function validateProjectId(req, res, next) {
 42→  const projectPath = resolveProjectPath(req.params.id);
 43→  if (!projectPath) {
 44→    return res.status(400).json({ error: 'Invalid project ID' });
 45→  }
 46→  if (!fs.existsSync(projectPath) || !fs.statSync(projectPath).isDirectory()) {
 47→    return res.status(404).json({ error: 'Project directory not found' });
 48→  }
 49→  req.projectPath = projectPath;
 50→  next();
 51→}
 52→
 53→// --- Config Management ---
 54→function loadConfig() {
 55→  try {
 56→    if (fs.existsSync(CONFIG_PATH)) {
 57→      return JSON.parse(fs.readFileSync(CONFIG_PATH, 'utf-8'));
 58→    }
 59→  } catch {}
 60→  return { projectDirs: [] };
 61→}
 62→
 63→function saveConfig(config) {
 64→  fs.writeFileSync(CONFIG_PATH, JSON.stringify(config, null, 2));
 65→}
 66→
 67→// --- Helpers ---
 68→function ensureDir(dir) {
 69→  if (!fs.existsSync(dir)) fs.mkdirSync(dir, { recursive: true });
 70→}
 71→
 72→function readFileSafe(filePath) {
 73→  try {
 74→    if (fs.existsSync(filePath)) return fs.readFileSync(filePath, 'utf-8');
 75→  } catch {}
 76→  return null;
 77→}
 78→
 79→function parseAgent(filePath) {
 80→  try {
 81→    const content = fs.readFileSync(filePath, 'utf-8');
 82→    const { data, content: body } = matter(content);
 83→    const stats = fs.statSync(filePath);
 84→    return {
 85→      filename: path.basename(filePath, '.md'),
 86→      path: filePath,
 87→      frontmatter: data,
 88→      name: data.name || path.basename(filePath, '.md'),
 89→      description: data.description || '',
 90→      model: data.model || '',
 91→      tools: data.tools || '',
 92→      body: body.trim(),
 93→      raw: content,
 94→      updatedAt: stats.mtime.toISOString(),
 95→    };
 96→  } catch (e) {
 97→    return null;
 98→  }
 99→}
100→
101→function listAgents(dir) {
102→  try {
103→    if (!fs.existsSync(dir)) return [];
104→    return fs.readdirSync(dir)
105→      .filter(f => f.endsWith('.md'))
106→      .map(f => parseAgent(path.join(dir, f)))
107→      .filter(Boolean);
108→  } catch {
109→    return [];
110→  }
111→}
112→
113→function listMdFiles(dir) {
114→  try {
115→    if (!fs.existsSync(dir)) return [];
116→    return fs.readdirSync(dir)
117→      .filter(f => f.endsWith('.md'))
118→      .map(f => {
119→        const filePath = path.join(dir, f);
120→        const content = readFileSafe(filePath);
121→        const stats = fs.statSync(filePath);
122→        return {
123→          name: f.replace('.md', ''),
124→          content: content || '',
125→          path: filePath,
126→          updatedAt: stats.mtime.toISOString(),
127→        };
128→      });
129→  } catch {
130→    return [];
131→  }
132→}
133→
134→function discoverProjects(dirs) {
135→  const projects = [];
136→  for (const dir of dirs) {
137→    const resolved = dir.replace(/^~/, HOME);
138→    if (!fs.existsSync(resolved)) continue;
139→    try {
140→      const entries = fs.readdirSync(resolved, { withFileTypes: true });
141→      for (const entry of entries) {
142→        if (!entry.isDirectory()) continue;
143→        if (entry.name.startsWith('.') || entry.name === 'node_modules') continue;
144→        const projectPath = path.join(resolved, entry.name);
145→        const hasClaudeDir = fs.existsSync(path.join(projectPath, '.claude'));
146→        const hasClaudeMd = fs.existsSync(path.join(projectPath, 'CLAUDE.md'));
147→        const hasPackageJson = fs.existsSync(path.join(projectPath, 'package.json'));
148→        const hasPubspec = fs.existsSync(path.join(projectPath, 'pubspec.yaml'));
149→        if (hasClaudeDir || hasClaudeMd || hasPackageJson || hasPubspec) {
150→          const agents = listAgents(path.join(projectPath, '.claude', 'agents'));
151→          const commands = listMdFiles(path.join(projectPath, '.claude', 'commands'));
152→          const rules = listMdFiles(path.join(projectPath, '.claude', 'rules'));
153→          projects.push({
154→            id: Buffer.from(projectPath).toString('base64url'),
155→            name: entry.name,
156→            path: projectPath,
157→            displayPath: projectPath.replace(HOME, '~'),
158→            hasClaudeDir,
159→            hasClaudeMd,
160→            agentCount: agents.length,
161→            commandCount: commands.length,
162→            ruleCount: rules.length,
163→            agents,
164→            commands: commands.map(c => c.name),
165→            rules: rules.map(r => r.name),
166→          });
167→        }
168→      }
169→    } catch {}
170→  }
171→  return projects;
172→}
173→
174→// --- API Routes ---
175→
176→// Config
177→app.get('/api/config', (req, res) => {
178→  const config = loadConfig();
179→  res.json({
180→    claudeDir: CLAUDE_DIR,
181→    claudeDirExists: fs.existsSync(CLAUDE_DIR),
182→    home: HOME,
183→    ...config,
184→  });
185→});
186→
187→app.post('/api/config/project-dirs', (req, res) => {
188→  const { dirs } = req.body;
189→  if (!Array.isArray(dirs)) return res.status(400).json({ error: 'dirs must be an array' });
190→  const config = loadConfig();
191→  config.projectDirs = dirs;
192→  saveConfig(config);
193→  res.json({ ok: true });
194→});
195→
196→
197→// Global CLAUDE.md
198→app.get('/api/global/claude-md', (req, res) => {
199→  const content = readFileSafe(path.join(CLAUDE_DIR, 'CLAUDE.md'));
200→  res.json({ content: content || '', exists: content !== null });
201→});
202→
203→app.put('/api/global/claude-md', (req, res) => {
204→  if (typeof req.body.content !== 'string') return res.status(400).json({ error: 'content must be a string' });
205→  ensureDir(CLAUDE_DIR);
206→  fs.writeFileSync(path.join(CLAUDE_DIR, 'CLAUDE.md'), req.body.content);
207→  res.json({ ok: true });
208→});
209→
210→// Global Agents
211→app.get('/api/global/agents', (req, res) => {
212→  const agents = listAgents(path.join(CLAUDE_DIR, 'agents'));
213→  res.json(agents);
214→});
215→
216→app.get('/api/global/agents/:name', validateName, (req, res) => {
217→  const agent = parseAgent(path.join(CLAUDE_DIR, 'agents', req.params.name + '.md'));
218→  if (!agent) return res.status(404).json({ error: 'Not found' });
219→  res.json(agent);
220→});
221→
222→app.put('/api/global/agents/:name', validateName, (req, res) => {
223→  if (typeof req.body.content !== 'string') return res.status(400).json({ error: 'content must be a string' });
224→  const dir = path.join(CLAUDE_DIR, 'agents');
225→  ensureDir(dir);
226→  const filePath = path.join(dir, req.params.name + '.md');
227→  fs.writeFileSync(filePath, req.body.content);
228→  res.json({ ok: true, agent: parseAgent(filePath) });
229→});
230→
231→app.delete('/api/global/agents/:name', validateName, (req, res) => {
232→  const filePath = path.join(CLAUDE_DIR, 'agents', req.params.name + '.md');
233→  if (fs.existsSync(filePath)) fs.unlinkSync(filePath);
234→  res.json({ ok: true });
235→});
236→
237→// Projects
238→app.get('/api/projects', (req, res) => {
239→  const config = loadConfig();
240→  const projects = discoverProjects(config.projectDirs);
241→  res.json(projects);
242→});
243→
244→// Project CLAUDE.md
245→app.get('/api/projects/:id/claude-md', validateProjectId, (req, res) => {
246→  const content = readFileSafe(path.join(req.projectPath, 'CLAUDE.md'));
247→  res.json({ content: content || '', exists: content !== null, path: req.projectPath });
248→});
249→
250→app.put('/api/projects/:id/claude-md', validateProjectId, (req, res) => {
251→  if (typeof req.body.content !== 'string') return res.status(400).json({ error: 'content must be a string' });
252→  fs.writeFileSync(path.join(req.projectPath, 'CLAUDE.md'), req.body.content);
253→  res.json({ ok: true });
254→});
255→
256→// Project Agents
257→app.get('/api/projects/:id/agents', validateProjectId, (req, res) => {
258→  const agents = listAgents(path.join(req.projectPath, '.claude', 'agents'));
259→  res.json(agents);
260→});
261→
262→app.get('/api/projects/:id/agents/:name', validateProjectId, validateName, (req, res) => {
263→  const agent = parseAgent(path.join(req.projectPath, '.claude', 'agents', req.params.name + '.md'));
264→  if (!agent) return res.status(404).json({ error: 'Not found' });
265→  res.json(agent);
266→});
267→
268→app.put('/api/projects/:id/agents/:name', validateProjectId, validateName, (req, res) => {
269→  if (typeof req.body.content !== 'string') return res.status(400).json({ error: 'content must be a string' });
270→  const dir = path.join(req.projectPath, '.claude', 'agents');
271→  ensureDir(dir);
272→  const filePath = path.join(dir, req.params.name + '.md');
273→  fs.writeFileSync(filePath, req.body.content);
274→  res.json({ ok: true, agent: parseAgent(filePath) });
275→});
276→
277→app.delete('/api/projects/:id/agents/:name', validateProjectId, validateName, (req, res) => {
278→  const filePath = path.join(req.projectPath, '.claude', 'agents', req.params.name + '.md');
279→  if (fs.existsSync(filePath)) fs.unlinkSync(filePath);
280→  res.json({ ok: true });
281→});
282→
283→// Project Commands (full CRUD)
284→app.get('/api/projects/:id/commands', validateProjectId, (req, res) => {
285→  res.json(listMdFiles(path.join(req.projectPath, '.claude', 'commands')));
286→});
287→
288→app.get('/api/projects/:id/commands/:name', validateProjectId, validateName, (req, res) => {
289→  const filePath = path.join(req.projectPath, '.claude', 'commands', req.params.name + '.md');
290→  const content = readFileSafe(filePath);
291→  if (content === null) return res.status(404).json({ error: 'Not found' });
292→  let updatedAt = new Date().toISOString();
293→  try { updatedAt = fs.statSync(filePath).mtime.toISOString(); } catch {}
294→  res.json({ name: req.params.name, content, path: filePath, updatedAt });
295→});
296→
297→app.put('/api/projects/:id/commands/:name', validateProjectId, validateName, (req, res) => {
298→  if (typeof req.body.content !== 'string') return res.status(400).json({ error: 'content must be a string' });
299→  const dir = path.join(req.projectPath, '.claude', 'commands');
300→  ensureDir(dir);
301→  const filePath = path.join(dir, req.params.name + '.md');
302→  fs.writeFileSync(filePath, req.body.content);
303→  const stats = fs.statSync(filePath);
304→  res.json({ ok: true, command: { name: req.params.name, content: req.body.content, path: filePath, updatedAt: stats.mtime.toISOString() } });
305→});
306→
307→app.delete('/api/projects/:id/commands/:name', validateProjectId, validateName, (req, res) => {
308→  const filePath = path.join(req.projectPath, '.claude', 'commands', req.params.name + '.md');
309→  if (fs.existsSync(filePath)) fs.unlinkSync(filePath);
310→  res.json({ ok: true });
311→});
312→
313→// Project Rules (full CRUD)
314→app.get('/api/projects/:id/rules', validateProjectId, (req, res) => {
315→  res.json(listMdFiles(path.join(req.projectPath, '.claude', 'rules')));
316→});
317→
318→app.get('/api/projects/:id/rules/:name', validateProjectId, validateName, (req, res) => {
319→  const filePath = path.join(req.projectPath, '.claude', 'rules', req.params.name + '.md');
320→  const content = readFileSafe(filePath);
321→  if (content === null) return res.status(404).json({ error: 'Not found' });
322→  let updatedAt = new Date().toISOString();
323→  try { updatedAt = fs.statSync(filePath).mtime.toISOString(); } catch {}
324→  res.json({ name: req.params.name, content, path: filePath, updatedAt });
