332→  fs.writeFileSync(filePath, req.body.content);
333→  const stats = fs.statSync(filePath);
334→  res.json({ ok: true, rule: { name: req.params.name, content: req.body.content, path: filePath, updatedAt: stats.mtime.toISOString() } });
335→});
336→
337→app.delete('/api/projects/:id/rules/:name', validateProjectId, validateName, (req, res) => {
338→  const filePath = path.join(req.projectPath, '.claude', 'rules', req.params.name + '.md');
339→  if (fs.existsSync(filePath)) fs.unlinkSync(filePath);
340→  res.json({ ok: true });
341→});
342→
343→// --- Directory Browser ---
344→app.get('/api/browse', (req, res) => {
345→  let targetPath = (req.query.path || HOME).replace(/^~/, HOME);
346→  targetPath = path.resolve(targetPath);
347→
348→  try {
349→    if (!fs.existsSync(targetPath)) {
350→      return res.status(404).json({ error: 'Path not found' });
351→    }
352→    const stat = fs.statSync(targetPath);
353→    if (!stat.isDirectory()) {
354→      return res.status(400).json({ error: 'Not a directory' });
355→    }
356→
357→    const entries = fs.readdirSync(targetPath, { withFileTypes: true });
358→    const dirs = entries
359→      .filter(e => e.isDirectory() && !e.name.startsWith('.') && e.name !== 'node_modules' && e.name !== '__pycache__')
360→      .map(e => ({
361→        name: e.name,
362→        path: path.join(targetPath, e.name),
363→        displayPath: path.join(targetPath, e.name).replace(HOME, '~'),
364→        hasProjects: false,
365→      }))
366→      .sort((a, b) => a.name.localeCompare(b.name));
367→
368→    for (const dir of dirs) {
369→      try {
