672→  proc.on('error', (err) => {
673→    res.status(500).json({ error: `Failed to run claude: ${err.message}` });
674→  });
675→
676→  // Write prompt via stdin and close
677→  proc.stdin.write(prompt, 'utf8');
678→  proc.stdin.end();
679→});
