781→// Topological sort helper
782→function topoSort(nodes, edges) {
783→  const inDegree = {};
784→  const adj = {};
785→  for (const n of nodes) { inDegree[n.id] = 0; adj[n.id] = []; }
786→  for (const e of edges) {
787→    adj[e.source].push(e.target);
788→    inDegree[e.target] = (inDegree[e.target] || 0) + 1;
789→  }
790→  const queue = nodes.filter(n => inDegree[n.id] === 0).map(n => n.id);
791→  const order = [];
792→  while (queue.length) {
793→    const id = queue.shift();
794→    order.push(id);
795→    for (const next of adj[id]) {
796→      inDegree[next]--;
797→      if (inDegree[next] === 0) queue.push(next);
798→    }
799→  }
800→  return order;
801→}
802→
803→function runClaudeSync(prompt, timeoutMs = 120000) {
804→  return new Promise((resolve, reject) => {
805→    const claudePath = process.env.CLAUDE_PATH || 'claude';
806→    const childEnv = { ...process.env, HOME: os.homedir() };
807→    delete childEnv.CLAUDECODE;
808→    const proc = spawn(claudePath, ['-p'], { env: childEnv });
809→    let out = '', err = '';
810→    let killed = false;
811→
812→    const timer = setTimeout(() => {
813→      killed = true;
814→      proc.kill('SIGTERM');
815→      setTimeout(() => { try { proc.kill('SIGKILL'); } catch {} }, 5000);
816→    }, timeoutMs);
817→
818→    proc.stdout.on('data', d => { out += d.toString(); });
819→    proc.stderr.on('data', d => { err += d.toString(); });
820→    proc.on('close', code => {
821→      clearTimeout(timer);
822→      if (killed) reject(new Error(`Node execution timed out after ${timeoutMs / 1000}s`));
823→      else if (code !== 0) reject(new Error(err.trim() || `claude exited ${code}`));
824→      else resolve(out.trim());
825→    });
826→    proc.on('error', (e) => { clearTimeout(timer); reject(e); });
827→    proc.stdin.write(prompt, 'utf8');
828→    proc.stdin.end();
829→  });
830→}
