832→app.post('/api/orchestrations/run', async (req, res) => {
833→  res.setTimeout(0);
834→  const { nodes, edges, task } = req.body;
835→  if (!Array.isArray(nodes) || !task) return res.status(400).json({ error: 'nodes and task required' });
836→
837→  const nodeMap = Object.fromEntries(nodes.map(n => [n.id, n]));
838→  const order = topoSort(nodes, edges || []);
839→
840→  // Build agent content map from files
841→  const config = loadConfig();
842→  const projects = discoverProjects(config.projectDirs);
843→  const agentContentMap = {};
844→
845→  const globalAgents = listAgents(path.join(CLAUDE_DIR, 'agents'));
846→  for (const a of globalAgents) agentContentMap[a.name] = a.body || a.raw;
847→
848→  for (const p of projects) {
849→    for (const a of p.agents) agentContentMap[a.name] = a.body || a.raw;
850→  }
851→
852→  const results = {};
853→  let lastOutput = task;
854→
855→  // SSE for streaming progress
856→  res.setHeader('Content-Type', 'text/event-stream');
857→  res.setHeader('Cache-Control', 'no-cache');
858→  res.setHeader('Connection', 'keep-alive');
859→
860→  const send = (data) => res.write(`data: ${JSON.stringify(data)}\n\n`);
861→
862→  try {
863→    for (const nodeId of order) {
864→      const node = nodeMap[nodeId];
865→      if (!node) continue;
866→
867→      // Skip start/task-input nodes — store task as their output for downstream nodes
868→      if (node.data?.isStart) {
869→        results[nodeId] = task;
870→        send({ type: 'done', nodeId, label: node.data?.label || nodeId, output: task, skipped: true });
871→        continue;
872→      }
873→
874→      const agentName = node.data?.agentName;
875→      const agentInstructions = agentName ? (agentContentMap[agentName] || '') : (node.data?.instructions || '');
876→      const nodeLabel = node.data?.label || agentName || nodeId;
877→
878→      send({ type: 'start', nodeId, label: nodeLabel });
879→
880→      // Build prompt for this agent
881→      const incomingEdges = (edges || []).filter(e => e.target === nodeId);
882→      let context = '';
883→      if (incomingEdges.length > 0) {
884→        context = incomingEdges.map(e => {
885→          const prevLabel = nodeMap[e.source]?.data?.label || e.source;
886→          return `## Output from ${prevLabel}:\n${results[e.source] || ''}`;
887→        }).join('\n\n');
888→      } else {
889→        context = `## Task:\n${task}`;
890→      }
891→
892→      const prompt = agentInstructions
893→        ? `${agentInstructions}\n\n---\n\n${context}\n\nProvide your response:`
894→        : `${context}\n\nProvide your response:`;
895→
896→      try {
897→        const output = await runClaudeSync(prompt);
898→        results[nodeId] = output;
899→        lastOutput = output;
900→        send({ type: 'done', nodeId, label: nodeLabel, output });
901→      } catch (err) {
902→        send({ type: 'error', nodeId, label: nodeLabel, error: err.message });
903→        break;
904→      }
905→    }
906→    send({ type: 'complete', finalOutput: lastOutput });
907→  } catch (err) {
908→    send({ type: 'error', nodeId: null, label: null, error: err.message });
909→  }
910→
911→  res.end();
912→});
