const express = require('express');
const fs = require('fs');
const path = require('path');
const os = require('os');
const matter = require('gray-matter');

const app = express();
app.use(express.json({ limit: '5mb' }));
// Serve built React frontend, fallback to legacy public/
const distPath = path.join(__dirname, '..', 'public-dist');
const legacyPath = path.join(__dirname, '..', 'public');
const staticPath = fs.existsSync(distPath) ? distPath : legacyPath;
app.use(express.static(staticPath));

const HOME = os.homedir();
const CLAUDE_DIR = path.join(HOME, '.claude');
const CONFIG_PATH = path.join(__dirname, '..', 'config.json');
const HISTORY_PATH = path.join(__dirname, '..', 'chat-history.json');
const ORCHESTRATIONS_PATH = path.join(__dirname, '..', 'orchestrations.json');

// --- Security: Name & Path Validation ---
function isValidName(name) {
  return /^[a-zA-Z0-9_-]+$/.test(name) && !name.includes('..');
}

function validateName(req, res, next) {
  if (!isValidName(req.params.name)) {
    return res.status(400).json({ error: 'Invalid name. Only letters, numbers, hyphens and underscores allowed.' });
  }
  next();
}

function resolveProjectPath(id) {
  try {
    return Buffer.from(id, 'base64url').toString();
  } catch {
    return null;
  }
}

function validateProjectId(req, res, next) {
  const projectPath = resolveProjectPath(req.params.id);
  if (!projectPath) {
    return res.status(400).json({ error: 'Invalid project ID' });
  }
  if (!fs.existsSync(projectPath) || !fs.statSync(projectPath).isDirectory()) {
    return res.status(404).json({ error: 'Project directory not found' });
  }
  req.projectPath = projectPath;
  next();
}

// --- Config Management ---
function loadConfig() {
  try {
    if (fs.existsSync(CONFIG_PATH)) {
      return JSON.parse(fs.readFileSync(CONFIG_PATH, 'utf-8'));
    }
  } catch {}
  return { projectDirs: [] };
}

function saveConfig(config) {
  fs.writeFileSync(CONFIG_PATH, JSON.stringify(config, null, 2));
}

// --- Helpers ---
function ensureDir(dir) {
  if (!fs.existsSync(dir)) fs.mkdirSync(dir, { recursive: true });
}

function readFileSafe(filePath) {
  try {
    if (fs.existsSync(filePath)) return fs.readFileSync(filePath, 'utf-8');
  } catch {}
  return null;
}

function parseAgent(filePath) {
  try {
    const content = fs.readFileSync(filePath, 'utf-8');
    const { data, content: body } = matter(content);
    const stats = fs.statSync(filePath);
    return {
      filename: path.basename(filePath, '.md'),
      path: filePath,
      frontmatter: data,
      name: data.name || path.basename(filePath, '.md'),
      description: data.description || '',
      model: data.model || '',
      tools: data.tools || '',
      body: body.trim(),
      raw: content,
      updatedAt: stats.mtime.toISOString(),
    };
  } catch (e) {
    return null;
  }
}

function listAgents(dir) {
  try {
    if (!fs.existsSync(dir)) return [];
    return fs.readdirSync(dir)
      .filter(f => f.endsWith('.md'))
      .map(f => parseAgent(path.join(dir, f)))
      .filter(Boolean);
  } catch {
    return [];
  }
}

function listMdFiles(dir) {
  try {
    if (!fs.existsSync(dir)) return [];
    return fs.readdirSync(dir)
      .filter(f => f.endsWith('.md'))
      .map(f => {
        const filePath = path.join(dir, f);
        const content = readFileSafe(filePath);
        const stats = fs.statSync(filePath);
        return {
          name: f.replace('.md', ''),
          content: content || '',
          path: filePath,
          updatedAt: stats.mtime.toISOString(),
        };
      });
  } catch {
    return [];
  }
}

function discoverProjects(dirs) {
  const projects = [];
  for (const dir of dirs) {
    const resolved = dir.replace(/^~/, HOME);
    if (!fs.existsSync(resolved)) continue;
    try {
      const entries = fs.readdirSync(resolved, { withFileTypes: true });
      for (const entry of entries) {
        if (!entry.isDirectory()) continue;
        if (entry.name.startsWith('.') || entry.name === 'node_modules') continue;
        const projectPath = path.join(resolved, entry.name);
        const hasClaudeDir = fs.existsSync(path.join(projectPath, '.claude'));
        const hasClaudeMd = fs.existsSync(path.join(projectPath, 'CLAUDE.md'));
        const hasPackageJson = fs.existsSync(path.join(projectPath, 'package.json'));
        const hasPubspec = fs.existsSync(path.join(projectPath, 'pubspec.yaml'));
        if (hasClaudeDir || hasClaudeMd || hasPackageJson || hasPubspec) {
          const agents = listAgents(path.join(projectPath, '.claude', 'agents'));
          const commands = listMdFiles(path.join(projectPath, '.claude', 'commands'));
          const rules = listMdFiles(path.join(projectPath, '.claude', 'rules'));
          projects.push({
            id: Buffer.from(projectPath).toString('base64url'),
            name: entry.name,
            path: projectPath,
            displayPath: projectPath.replace(HOME, '~'),
            hasClaudeDir,
            hasClaudeMd,
            agentCount: agents.length,
            commandCount: commands.length,
            ruleCount: rules.length,
            agents,
            commands: commands.map(c => c.name),
            rules: rules.map(r => r.name),
          });
        }
      }
    } catch {}
  }
  return projects;
}

// --- API Routes ---

// Config
app.get('/api/config', (req, res) => {
  const config = loadConfig();
  res.json({
    claudeDir: CLAUDE_DIR,
    claudeDirExists: fs.existsSync(CLAUDE_DIR),
    home: HOME,
    ...config,
  });
});

app.post('/api/config/project-dirs', (req, res) => {
  const { dirs } = req.body;
  if (!Array.isArray(dirs)) return res.status(400).json({ error: 'dirs must be an array' });
  const config = loadConfig();
  config.projectDirs = dirs;
  saveConfig(config);
  res.json({ ok: true });
});


// Global CLAUDE.md
app.get('/api/global/claude-md', (req, res) => {
  const content = readFileSafe(path.join(CLAUDE_DIR, 'CLAUDE.md'));
  res.json({ content: content || '', exists: content !== null });
});

app.put('/api/global/claude-md', (req, res) => {
  if (typeof req.body.content !== 'string') return res.status(400).json({ error: 'content must be a string' });
  ensureDir(CLAUDE_DIR);
  fs.writeFileSync(path.join(CLAUDE_DIR, 'CLAUDE.md'), req.body.content);
  res.json({ ok: true });
});

// Global Agents
app.get('/api/global/agents', (req, res) => {
  const agents = listAgents(path.join(CLAUDE_DIR, 'agents'));
  res.json(agents);
});

app.get('/api/global/agents/:name', validateName, (req, res) => {
  const agent = parseAgent(path.join(CLAUDE_DIR, 'agents', req.params.name + '.md'));
  if (!agent) return res.status(404).json({ error: 'Not found' });
  res.json(agent);
});

app.put('/api/global/agents/:name', validateName, (req, res) => {
  if (typeof req.body.content !== 'string') return res.status(400).json({ error: 'content must be a string' });
  const dir = path.join(CLAUDE_DIR, 'agents');
  ensureDir(dir);
  const filePath = path.join(dir, req.params.name + '.md');
  fs.writeFileSync(filePath, req.body.content);
  res.json({ ok: true, agent: parseAgent(filePath) });
});

app.delete('/api/global/agents/:name', validateName, (req, res) => {
  const filePath = path.join(CLAUDE_DIR, 'agents', req.params.name + '.md');
  if (fs.existsSync(filePath)) fs.unlinkSync(filePath);
  res.json({ ok: true });
});

// Projects
app.get('/api/projects', (req, res) => {
  const config = loadConfig();
  const projects = discoverProjects(config.projectDirs);
  res.json(projects);
});

// Project CLAUDE.md
app.get('/api/projects/:id/claude-md', validateProjectId, (req, res) => {
  const content = readFileSafe(path.join(req.projectPath, 'CLAUDE.md'));
  res.json({ content: content || '', exists: content !== null, path: req.projectPath });
});

app.put('/api/projects/:id/claude-md', validateProjectId, (req, res) => {
  if (typeof req.body.content !== 'string') return res.status(400).json({ error: 'content must be a string' });
  fs.writeFileSync(path.join(req.projectPath, 'CLAUDE.md'), req.body.content);
  res.json({ ok: true });
});

// Project Agents
app.get('/api/projects/:id/agents', validateProjectId, (req, res) => {
  const agents = listAgents(path.join(req.projectPath, '.claude', 'agents'));
  res.json(agents);
});

app.get('/api/projects/:id/agents/:name', validateProjectId, validateName, (req, res) => {
  const agent = parseAgent(path.join(req.projectPath, '.claude', 'agents', req.params.name + '.md'));
  if (!agent) return res.status(404).json({ error: 'Not found' });
  res.json(agent);
});

app.put('/api/projects/:id/agents/:name', validateProjectId, validateName, (req, res) => {
  if (typeof req.body.content !== 'string') return res.status(400).json({ error: 'content must be a string' });
  const dir = path.join(req.projectPath, '.claude', 'agents');
  ensureDir(dir);
  const filePath = path.join(dir, req.params.name + '.md');
  fs.writeFileSync(filePath, req.body.content);
  res.json({ ok: true, agent: parseAgent(filePath) });
});

app.delete('/api/projects/:id/agents/:name', validateProjectId, validateName, (req, res) => {
  const filePath = path.join(req.projectPath, '.claude', 'agents', req.params.name + '.md');
  if (fs.existsSync(filePath)) fs.unlinkSync(filePath);
  res.json({ ok: true });
});

// Project Commands (full CRUD)
app.get('/api/projects/:id/commands', validateProjectId, (req, res) => {
  res.json(listMdFiles(path.join(req.projectPath, '.claude', 'commands')));
});

app.get('/api/projects/:id/commands/:name', validateProjectId, validateName, (req, res) => {
  const filePath = path.join(req.projectPath, '.claude', 'commands', req.params.name + '.md');
  const content = readFileSafe(filePath);
  if (content === null) return res.status(404).json({ error: 'Not found' });
  let updatedAt = new Date().toISOString();
  try { updatedAt = fs.statSync(filePath).mtime.toISOString(); } catch {}
  res.json({ name: req.params.name, content, path: filePath, updatedAt });
});

app.put('/api/projects/:id/commands/:name', validateProjectId, validateName, (req, res) => {
  if (typeof req.body.content !== 'string') return res.status(400).json({ error: 'content must be a string' });
  const dir = path.join(req.projectPath, '.claude', 'commands');
  ensureDir(dir);
  const filePath = path.join(dir, req.params.name + '.md');
  fs.writeFileSync(filePath, req.body.content);
  const stats = fs.statSync(filePath);
  res.json({ ok: true, command: { name: req.params.name, content: req.body.content, path: filePath, updatedAt: stats.mtime.toISOString() } });
});

app.delete('/api/projects/:id/commands/:name', validateProjectId, validateName, (req, res) => {
  const filePath = path.join(req.projectPath, '.claude', 'commands', req.params.name + '.md');
  if (fs.existsSync(filePath)) fs.unlinkSync(filePath);
  res.json({ ok: true });
});

// Project Rules (full CRUD)
app.get('/api/projects/:id/rules', validateProjectId, (req, res) => {
  res.json(listMdFiles(path.join(req.projectPath, '.claude', 'rules')));
});

app.get('/api/projects/:id/rules/:name', validateProjectId, validateName, (req, res) => {
  const filePath = path.join(req.projectPath, '.claude', 'rules', req.params.name + '.md');
  const content = readFileSafe(filePath);
  if (content === null) return res.status(404).json({ error: 'Not found' });
  let updatedAt = new Date().toISOString();
  try { updatedAt = fs.statSync(filePath).mtime.toISOString(); } catch {}
  res.json({ name: req.params.name, content, path: filePath, updatedAt });
});

app.put('/api/projects/:id/rules/:name', validateProjectId, validateName, (req, res) => {
  if (typeof req.body.content !== 'string') return res.status(400).json({ error: 'content must be a string' });
  const dir = path.join(req.projectPath, '.claude', 'rules');
  ensureDir(dir);
  const filePath = path.join(dir, req.params.name + '.md');
  fs.writeFileSync(filePath, req.body.content);
  const stats = fs.statSync(filePath);
  res.json({ ok: true, rule: { name: req.params.name, content: req.body.content, path: filePath, updatedAt: stats.mtime.toISOString() } });
});

app.delete('/api/projects/:id/rules/:name', validateProjectId, validateName, (req, res) => {
  const filePath = path.join(req.projectPath, '.claude', 'rules', req.params.name + '.md');
  if (fs.existsSync(filePath)) fs.unlinkSync(filePath);
  res.json({ ok: true });
});

// --- Directory Browser ---
app.get('/api/browse', (req, res) => {
  let targetPath = (req.query.path || HOME).replace(/^~/, HOME);
  targetPath = path.resolve(targetPath);

  try {
    if (!fs.existsSync(targetPath)) {
      return res.status(404).json({ error: 'Path not found' });
    }
    const stat = fs.statSync(targetPath);
    if (!stat.isDirectory()) {
      return res.status(400).json({ error: 'Not a directory' });
    }

    const entries = fs.readdirSync(targetPath, { withFileTypes: true });
    const dirs = entries
      .filter(e => e.isDirectory() && !e.name.startsWith('.') && e.name !== 'node_modules' && e.name !== '__pycache__')
      .map(e => ({
        name: e.name,
        path: path.join(targetPath, e.name),
        displayPath: path.join(targetPath, e.name).replace(HOME, '~'),
        hasProjects: false,
      }))
      .sort((a, b) => a.name.localeCompare(b.name));

    for (const dir of dirs) {
      try {
        const sub = fs.readdirSync(dir.path, { withFileTypes: true });
        dir.hasProjects = sub.some(s =>
          s.isDirectory() && (
            fs.existsSync(path.join(dir.path, s.name, '.claude')) ||
            fs.existsSync(path.join(dir.path, s.name, 'CLAUDE.md')) ||
            fs.existsSync(path.join(dir.path, s.name, 'package.json')) ||
            fs.existsSync(path.join(dir.path, s.name, 'pubspec.yaml'))
          )
        );
      } catch {}
    }

    const parts = targetPath.split(path.sep).filter(Boolean);
    const breadcrumbs = parts.map((part, i) => ({
      name: i === 0 && targetPath.startsWith(HOME) ? '~' : part,
      path: path.sep + parts.slice(0, i + 1).join(path.sep),
    }));

    if (targetPath.startsWith(HOME)) {
      const homeIndex = HOME.split(path.sep).filter(Boolean).length - 1;
      breadcrumbs.splice(0, homeIndex + 1, { name: '~', path: HOME });
    }

    res.json({
      current: targetPath,
      displayPath: targetPath.replace(HOME, '~'),
      parent: path.dirname(targetPath) !== targetPath ? path.dirname(targetPath) : null,
      breadcrumbs,
      directories: dirs,
    });
  } catch (e) {
    res.status(500).json({ error: 'Cannot read directory' });
  }
});

// --- Unified endpoints ---

app.get('/api/unified/agents', (req, res) => {
  const config = loadConfig();
  const projects = discoverProjects(config.projectDirs);
  const results = [];

  const globalAgents = listAgents(path.join(CLAUDE_DIR, 'agents'));
  for (const agent of globalAgents) {
    results.push({ ...agent, scope: 'global', scopeLabel: 'Global', projectId: null, projectName: null });
  }

  for (const project of projects) {
    for (const agent of project.agents) {
      results.push({ ...agent, scope: 'project', scopeLabel: project.name, projectId: project.id, projectName: project.name });
    }
  }

  results.sort((a, b) => new Date(b.updatedAt) - new Date(a.updatedAt));
  res.json(results);
});

app.get('/api/unified/commands', (req, res) => {
  const config = loadConfig();
  const projects = discoverProjects(config.projectDirs);
  const results = [];

  for (const project of projects) {
    const cmds = listMdFiles(path.join(project.path, '.claude', 'commands'));
    for (const cmd of cmds) {
      results.push({ ...cmd, projectId: project.id, projectName: project.name });
    }
  }

  results.sort((a, b) => new Date(b.updatedAt) - new Date(a.updatedAt));
  res.json(results);
});

app.get('/api/unified/rules', (req, res) => {
  const config = loadConfig();
  const projects = discoverProjects(config.projectDirs);
  const results = [];

  for (const project of projects) {
    const rls = listMdFiles(path.join(project.path, '.claude', 'rules'));
    for (const rule of rls) {
      results.push({ ...rule, projectId: project.id, projectName: project.name });
    }
  }

  results.sort((a, b) => new Date(b.updatedAt) - new Date(a.updatedAt));
  res.json(results);
});

// Copy / Move agent between scopes
app.post('/api/copy-agent', (req, res) => {
  const { from, to, agentName } = req.body;
  if (!isValidName(agentName)) return res.status(400).json({ error: 'Invalid agent name' });

  let srcPath, destDir;
  if (from === 'global') {
    srcPath = path.join(CLAUDE_DIR, 'agents', agentName + '.md');
  } else {
    const fromPath = resolveProjectPath(from);
    if (!fromPath) return res.status(400).json({ error: 'Invalid source project' });
    srcPath = path.join(fromPath, '.claude', 'agents', agentName + '.md');
  }
  if (to === 'global') {
    destDir = path.join(CLAUDE_DIR, 'agents');
  } else {
    const toPath = resolveProjectPath(to);
    if (!toPath) return res.status(400).json({ error: 'Invalid target project' });
    destDir = path.join(toPath, '.claude', 'agents');
  }
  ensureDir(destDir);
  const content = readFileSafe(srcPath);
  if (!content) return res.status(404).json({ error: 'Source agent not found' });
  fs.writeFileSync(path.join(destDir, agentName + '.md'), content);
  res.json({ ok: true });
});

app.post('/api/move-agent', (req, res) => {
  const { from, to, agentName } = req.body;
  if (!isValidName(agentName)) return res.status(400).json({ error: 'Invalid agent name' });

  let srcPath, destDir;
  if (from === 'global') {
    srcPath = path.join(CLAUDE_DIR, 'agents', agentName + '.md');
  } else {
    const fromPath = resolveProjectPath(from);
    if (!fromPath) return res.status(400).json({ error: 'Invalid source project' });
    srcPath = path.join(fromPath, '.claude', 'agents', agentName + '.md');
  }
  if (to === 'global') {
    destDir = path.join(CLAUDE_DIR, 'agents');
  } else {
    const toPath = resolveProjectPath(to);
    if (!toPath) return res.status(400).json({ error: 'Invalid target project' });
    destDir = path.join(toPath, '.claude', 'agents');
  }
  ensureDir(destDir);
  const content = readFileSafe(srcPath);
  if (!content) return res.status(404).json({ error: 'Source agent not found' });
  fs.writeFileSync(path.join(destDir, agentName + '.md'), content);
  if (fs.existsSync(srcPath)) fs.unlinkSync(srcPath);
  res.json({ ok: true });
});

// --- Chat History ---
function loadHistory() {
  try {
    if (fs.existsSync(HISTORY_PATH)) return JSON.parse(fs.readFileSync(HISTORY_PATH, 'utf-8'));
  } catch {}
  return [];
}

function saveHistory(history) {
  fs.writeFileSync(HISTORY_PATH, JSON.stringify(history, null, 2));
}

function genId() {
  return Date.now().toString(36) + Math.random().toString(36).slice(2, 7);
}

app.get('/api/ai/history', (req, res) => {
  const history = loadHistory();
  res.json(history.map(s => ({ id: s.id, title: s.title, updatedAt: s.updatedAt, messageCount: s.messages.length })));
});

app.get('/api/ai/history/:id', (req, res) => {
  const session = loadHistory().find(s => s.id === req.params.id);
  if (!session) return res.status(404).json({ error: 'Not found' });
  res.json(session);
});

app.post('/api/ai/history', (req, res) => {
  const { id, title, messages } = req.body;
  if (!Array.isArray(messages)) return res.status(400).json({ error: 'messages required' });
  const history = loadHistory();
  const now = new Date().toISOString();
  const sessionId = id || genId();
  const idx = history.findIndex(s => s.id === sessionId);
  const session = { id: sessionId, title: title || 'New Chat', messages, createdAt: now, updatedAt: now };
  if (idx >= 0) {
    session.createdAt = history[idx].createdAt;
    history[idx] = session;
  } else {
    history.unshift(session);
  }
  saveHistory(history.slice(0, 100));
  res.json({ id: sessionId });
});

app.delete('/api/ai/history/:id', (req, res) => {
  saveHistory(loadHistory().filter(s => s.id !== req.params.id));
  res.json({ ok: true });
});

// --- Full App Context for AI ---
app.get('/api/ai/context', (req, res) => {
  const config = loadConfig();
  const projects = discoverProjects(config.projectDirs);
  const globalAgentsList = listAgents(path.join(CLAUDE_DIR, 'agents'));
  const globalClaudeMdContent = readFileSafe(path.join(CLAUDE_DIR, 'CLAUDE.md'));

  const ctx = {
    globalClaudeMd: {
      path: path.join(CLAUDE_DIR, 'CLAUDE.md'),
      content: globalClaudeMdContent || '',
    },
    globalAgentsDir: path.join(CLAUDE_DIR, 'agents'),
    globalAgents: globalAgentsList.map(a => ({
      name: a.name,
      description: a.description,
      path: path.join(CLAUDE_DIR, 'agents', a.filename + '.md'),
      content: a.raw,
    })),
    projects: projects.map(p => ({
      name: p.name,
      path: p.path,
      agentsDir: path.join(p.path, '.claude', 'agents'),
      commandsDir: path.join(p.path, '.claude', 'commands'),
      rulesDir: path.join(p.path, '.claude', 'rules'),
      claudeMd: {
        path: path.join(p.path, 'CLAUDE.md'),
        content: readFileSafe(path.join(p.path, 'CLAUDE.md')) || '',
      },
      agents: p.agents.map(a => ({
        name: a.name,
        description: a.description,
        path: path.join(p.path, '.claude', 'agents', a.filename + '.md'),
        content: a.raw,
      })),
      commands: listMdFiles(path.join(p.path, '.claude', 'commands')).map(c => ({
        name: c.name, path: c.path, content: c.content,
      })),
      rules: listMdFiles(path.join(p.path, '.claude', 'rules')).map(r => ({
        name: r.name, path: r.path, content: r.content,
      })),
    })),
  };

  res.json(ctx);
});

// --- Apply AI-suggested file write ---
app.post('/api/ai/apply', (req, res) => {
  const { filePath, content } = req.body;
  if (!filePath || typeof content !== 'string') {
    return res.status(400).json({ error: 'filePath and content required' });
  }

  const resolved = path.resolve(filePath.replace(/^~/, HOME));
  const config = loadConfig();
