    fullOutput += chunk;
    res.write(`data: ${JSON.stringify({ type: 'chunk', content: chunk })}\n\n`);
  });

  proc.stderr.on('data', () => {});

  proc.on('close', (code) => {
    if (code !== 0) {
      res.write(`data: ${JSON.stringify({ type: 'error', error: 'Claude process failed' })}\n\n`);
    } else {
      res.write(`data: ${JSON.stringify({ type: 'done', content: fullOutput.trim() })}\n\n`);
    }
    res.end();
  });

  proc.on('error', (err) => {
    res.write(`data: ${JSON.stringify({ type: 'error', error: err.message })}\n\n`);
