import { useState, useCallback, useRef, useEffect, useMemo } from 'react'
import {
  ReactFlow,
  Background,
  Controls,
  MiniMap,
  addEdge,
  useNodesState,
  useEdgesState,
  type Connection,
  type Node,
  type Edge,
  type NodeTypes,
  Handle,
  Position,
  BackgroundVariant,
  type ReactFlowInstance,
} from '@xyflow/react'
import '@xyflow/react/dist/style.css'
import {
  Play, Save, Trash2, Plus, Zap, ChevronRight,
  CheckCircle, AlertCircle, Loader, Terminal, FileText,
  LayoutTemplate, X, Sparkles, Copy, Settings2, RotateCcw, HelpCircle,
} from 'lucide-react'
import { getUnifiedAgents } from '../lib/api'
import { useApi } from '../hooks/useApi'
import type { UnifiedAgent } from '../types'
import { toast } from '../components/Toast'
import AgentIcon from '../components/AgentIcon'

// ---- Custom Node ----
interface AgentNodeData {
  label: string
  agentName?: string
  scope?: string
  description?: string
  instructions?: string
  status?: 'idle' | 'running' | 'done' | 'error'
  output?: string
  isStart?: boolean
  isCustom?: boolean
  executionOrder?: number
  [key: string]: unknown
}

function AgentNode({ data, selected }: { data: AgentNodeData; selected: boolean }) {
  const statusColor = {
    idle: 'border-border',
    running: 'border-purple animate-pulse',
    done: 'border-green',
    error: 'border-red',
  }[data.status || 'idle']

  return (
    <div
      className={`relative min-w-[180px] max-w-[220px] rounded-xl border-2 bg-surface shadow-lg transition-all ${statusColor} ${selected ? 'ring-2 ring-accent/40' : ''}`}
    >
      {data.executionOrder != null && (
        <span className="absolute -top-2.5 -left-2.5 w-5 h-5 rounded-full bg-purple text-white text-[10px] font-bold flex items-center justify-center shadow-md z-10">
          {data.executionOrder}
        </span>
      )}
      <Handle type="target" position={Position.Left} className="!w-3 !h-3 !bg-accent !border-2 !border-surface" />

      <div className="px-3.5 pt-3 pb-2.5">
        <div className="flex items-center gap-2 mb-1.5">
          {data.isStart ? (
            <div className="w-6 h-6 rounded-md bg-accent flex items-center justify-center shrink-0">
              <Zap className="w-3.5 h-3.5 text-white" />
            </div>
          ) : data.isCustom ? (
            <div className="w-6 h-6 rounded-md bg-amber-muted flex items-center justify-center shrink-0">
              <Terminal className="w-3.5 h-3.5 text-amber" />
            </div>
          ) : (
            <AgentIcon
              name={data.label as string}
              uid={`node-icon-${data.label}`}
              size={24}
              global={!data.agentName || data.scope === 'Global'}
            />
          )}
          <div className="min-w-0">
            <p className="text-[12px] font-semibold leading-tight truncate">{data.label}</p>
            {data.scope && <p className="text-[10px] text-text-muted">{data.scope}</p>}
          </div>
          {data.status === 'running' && <Loader className="w-3.5 h-3.5 text-purple animate-spin ml-auto shrink-0" />}
          {data.status === 'done' && <CheckCircle className="w-3.5 h-3.5 text-green ml-auto shrink-0" />}
          {data.status === 'error' && <AlertCircle className="w-3.5 h-3.5 text-red ml-auto shrink-0" />}
        </div>

        {data.description && (
          <p className="text-[10px] text-text-muted leading-snug line-clamp-2">{data.description}</p>
        )}

        {data.output && (
          <div className="mt-2 pt-2 border-t border-border">
            <p className="text-[10px] text-text-muted mb-0.5">Output:</p>
            <p className="text-[10px] text-text leading-snug line-clamp-3">{data.output}</p>
          </div>
        )}
      </div>

      <Handle type="source" position={Position.Right} className="!w-3 !h-3 !bg-accent !border-2 !border-surface" />
    </div>
  )
}

const nodeTypes: NodeTypes = { agentNode: AgentNode }

// ---- Orchestration Templates ----
const TEMPLATES = [
  {
    name: 'Plan → Code → Review',
    description: 'Classic app-building pipeline',
    nodes: [
      { id: 'n1', type: 'agentNode', position: { x: 60, y: 180 }, data: { label: 'Task Input', isStart: true, description: 'Your initial task or feature request' } },
      { id: 'n2', type: 'agentNode', position: { x: 300, y: 80 }, data: { label: 'Planner', isCustom: true, description: 'Break task into implementation steps', instructions: 'You are a software architect. Break the given task into clear, actionable implementation steps. Output a numbered list of steps with technical details.' } },
      { id: 'n3', type: 'agentNode', position: { x: 300, y: 280 }, data: { label: 'Researcher', isCustom: true, description: 'Research best approaches and patterns', instructions: 'You are a research expert. Given the task, identify the best libraries, patterns, and approaches. Output concise recommendations.' } },
      { id: 'n4', type: 'agentNode', position: { x: 560, y: 180 }, data: { label: 'Developer', isCustom: true, description: 'Write the implementation', instructions: 'You are a senior developer. Given the plan and research, write the full implementation. Output clean, production-grade code with comments.' } },
      { id: 'n5', type: 'agentNode', position: { x: 800, y: 180 }, data: { label: 'Reviewer', isCustom: true, description: 'Review and improve the code', instructions: 'You are a code reviewer. Review the implementation for bugs, security issues, and improvements. Output an improved version with explanations.' } },
    ],
    edges: [
      { id: 'e1', source: 'n1', target: 'n2', animated: true },
      { id: 'e2', source: 'n1', target: 'n3', animated: true },
      { id: 'e3', source: 'n2', target: 'n4', animated: true },
      { id: 'e4', source: 'n3', target: 'n4', animated: true },
      { id: 'e5', source: 'n4', target: 'n5', animated: true },
    ],
  },
  {
    name: 'Research → Write → Polish',
    description: 'Content & documentation pipeline',
    nodes: [
      { id: 'n1', type: 'agentNode', position: { x: 60, y: 150 }, data: { label: 'Topic Input', isStart: true, description: 'Topic or documentation request' } },
      { id: 'n2', type: 'agentNode', position: { x: 300, y: 150 }, data: { label: 'Researcher', isCustom: true, description: 'Gather key information', instructions: 'Research the given topic thoroughly. Extract key concepts, examples, and technical details.' } },
      { id: 'n3', type: 'agentNode', position: { x: 540, y: 150 }, data: { label: 'Writer', isCustom: true, description: 'Write structured content', instructions: 'Write clear, well-structured content based on the research. Use headers, examples, and clear language.' } },
      { id: 'n4', type: 'agentNode', position: { x: 780, y: 150 }, data: { label: 'Editor', isCustom: true, description: 'Polish and finalize', instructions: 'Edit and polish the content. Fix clarity, tone, structure. Output the final polished version.' } },
    ],
    edges: [
      { id: 'e1', source: 'n1', target: 'n2', animated: true },
      { id: 'e2', source: 'n2', target: 'n3', animated: true },
      { id: 'e3', source: 'n3', target: 'n4', animated: true },
    ],
  },
]

// ---- Run Log Entry ----
interface RunLog {
  nodeId: string | null
  label: string | null
  type: 'start' | 'done' | 'error' | 'complete'
  output?: string
  error?: string
  finalOutput?: string
}

// ---- Main Page ----
export default function Orchestration() {
  const { data: allAgents } = useApi(getUnifiedAgents)
  const [nodes, setNodes, onNodesChange] = useNodesState<Node>([])
  const [edges, setEdges, onEdgesChange] = useEdgesState<Edge>([])
  const [orchName, setOrchName] = useState('My Orchestration')
  const [orchId, setOrchId] = useState<string | null>(null)
  const [task, setTask] = useState('')
  const [saving, setSaving] = useState(false)
  const [running, setRunning] = useState(false)
  const abortRef = useRef<AbortController | null>(null)
  const [runLog, setRunLog] = useState<RunLog[]>([])
  const [showRunPanel, setShowRunPanel] = useState(false)
  const [showTemplates, setShowTemplates] = useState(false)
  const [savedList, setSavedList] = useState<{ id: string; name: string; updatedAt: string }[]>([])
  const [showSaved, setShowSaved] = useState(false)
  const [showClearConfirm, setShowClearConfirm] = useState(false)
  const [showGuide, setShowGuide] = useState(false)
  const [selectedNodeId, setSelectedNodeId] = useState<string | null>(null)
  const [viewingOutputNodeId, setViewingOutputNodeId] = useState<string | null>(null)

  // Use ref for ID counter — avoids stale closures in memoized callbacks
  const nodeCounterRef = useRef(100)
  const rfInstanceRef = useRef<ReactFlowInstance | null>(null)
  const logEndRef = useRef<HTMLDivElement | null>(null)
  const sseBufferRef = useRef('')

  const selectedNode = nodes.find(n => n.id === selectedNodeId) ?? null
  const viewingNode = nodes.find(n => n.id === viewingOutputNodeId) ?? null
  const viewingOutput = viewingNode ? (viewingNode.data as AgentNodeData).output : null

  // Compute topological execution order for display
  const executionOrder = useMemo(() => {
    const inDegree: Record<string, number> = {}
    const adj: Record<string, string[]> = {}
    for (const n of nodes) { inDegree[n.id] = 0; adj[n.id] = [] }
    for (const e of edges) {
      if (adj[e.source]) adj[e.source].push(e.target)
      inDegree[e.target] = (inDegree[e.target] || 0) + 1
    }
    const queue = nodes.filter(n => inDegree[n.id] === 0).map(n => n.id)
    const order: Record<string, number> = {}
    let step = 1
    while (queue.length) {
      const id = queue.shift()!
      order[id] = step++
      for (const next of (adj[id] || [])) {
        inDegree[next]--
        if (inDegree[next] === 0) queue.push(next)
      }
    }
    return order
  }, [nodes, edges])

  const nodesWithOrder = useMemo(() =>
    nodes.map(n => ({
      ...n,
      data: { ...n.data, executionOrder: executionOrder[n.id] }
    })) as Node[],
    [nodes, executionOrder]
  )

  // Auto-scroll run log to bottom
  useEffect(() => {
    logEndRef.current?.scrollIntoView({ behavior: 'smooth' })
  }, [runLog])

  const loadSaved = useCallback(async () => {
    try {
      const res = await fetch('/api/orchestrations')
      const data = await res.json()
      setSavedList(data)
    } catch {}
  }, [])

  useEffect(() => { loadSaved() }, [loadSaved])

  const onConnect = useCallback(
    (connection: Connection) => setEdges(eds => addEdge({ ...connection, animated: true }, eds)),
    [setEdges]
  )

  const onNodeClick = useCallback((_: React.MouseEvent, node: Node) => {
    const nd = node.data as AgentNodeData
    if (showRunPanel && (nd.status === 'done' || nd.status === 'error')) {
      setViewingOutputNodeId(node.id)
    } else {
      setSelectedNodeId(node.id)
    }
  }, [showRunPanel])

  const onPaneClick = useCallback(() => {
    setSelectedNodeId(null)
  }, [])

  const addAgentNode = useCallback((agent: UnifiedAgent) => {
    const id = `node-${nodeCounterRef.current++}`
    setNodes(nds => [...nds, {
      id,
      type: 'agentNode',
      position: { x: 200 + Math.random() * 300, y: 100 + Math.random() * 200 },
      data: {
        label: agent.name,
        agentName: agent.name,
        scope: agent.scopeLabel,
        description: agent.description,
        status: 'idle',
      },
    }])
  }, [setNodes])

  const addCustomNode = useCallback(() => {
    const id = `node-${nodeCounterRef.current++}`
    setNodes(nds => [...nds, {
      id,
      type: 'agentNode',
      position: { x: 200 + Math.random() * 300, y: 100 + Math.random() * 200 },
      data: {
        label: 'Custom Step',
        isCustom: true,
        description: 'Click to configure',
        instructions: '',
        status: 'idle',
      },
    }])
  }, [setNodes])

  const deleteSelectedNode = useCallback(() => {
    if (!selectedNodeId) return
    setNodes(nds => nds.filter(n => n.id !== selectedNodeId))
    setEdges(eds => eds.filter(e => e.source !== selectedNodeId && e.target !== selectedNodeId))
    setSelectedNodeId(null)
  }, [selectedNodeId, setNodes, setEdges])

  const updateSelectedNodeData = useCallback((patch: Partial<AgentNodeData>) => {
    if (!selectedNodeId) return
    setNodes(nds => nds.map(n =>
      n.id === selectedNodeId ? { ...n, data: { ...n.data, ...patch } } : n
    ))
  }, [selectedNodeId, setNodes])

  const loadTemplate = useCallback((tpl: typeof TEMPLATES[0]) => {
    if (nodes.length > 0 && !window.confirm(`Loading this template will replace your current ${nodes.length} nodes. Continue?`)) {
      return
    }
    setNodes(tpl.nodes.map(n => ({ ...n, data: { ...n.data, status: 'idle' } })) as Node[])
    setEdges(tpl.edges as Edge[])
    setOrchName(tpl.name)
    setOrchId(null)
    setShowTemplates(false)
    setRunLog([])
    setSelectedNodeId(null)
    setViewingOutputNodeId(null)
    // Fit view after template loads
    setTimeout(() => rfInstanceRef.current?.fitView({ padding: 0.15 }), 50)
  }, [setNodes, setEdges, nodes.length])

  const handleSave = async () => {
    setSaving(true)
    try {
      const res = await fetch('/api/orchestrations', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ id: orchId || undefined, name: orchName, nodes, edges }),
      })
      if (!res.ok) throw new Error(`Save failed: ${res.statusText}`)
      const data = await res.json()
      setOrchId(data.id)
      loadSaved()
      toast('success', 'Orchestration saved')
    } catch (err) {
      toast('error', err instanceof Error ? err.message : 'Failed to save orchestration')
    } finally {
      setSaving(false)
    }
  }

  const handleLoad = async (id: string) => {
    try {
      const res = await fetch(`/api/orchestrations/${id}`)
      if (!res.ok) throw new Error('Orchestration not found')
      const orc = await res.json()
      setNodes(orc.nodes.map((n: Node) => ({ ...n, data: { ...n.data, status: 'idle', output: undefined } })))
      setEdges(orc.edges)
      setOrchName(orc.name)
      setOrchId(orc.id)
      setRunLog([])
      setSelectedNodeId(null)
      setShowSaved(false)
      setTimeout(() => rfInstanceRef.current?.fitView({ padding: 0.15 }), 50)
    } catch (err) {
      toast('error', err instanceof Error ? err.message : 'Failed to load orchestration')
    }
  }

  const handleDelete = async (id: string) => {
    try {
      const res = await fetch(`/api/orchestrations/${id}`, { method: 'DELETE' })
      if (!res.ok) throw new Error('Delete failed')
      loadSaved()
      if (orchId === id) { setOrchId(null); setNodes([]); setEdges([]) }
      toast('success', 'Deleted')
    } catch (err) {
      toast('error', err instanceof Error ? err.message : 'Failed to delete orchestration')
    }
  }

  const clearCanvas = () => {
    setNodes([])
    setEdges([])
    setOrchId(null)
    setRunLog([])
    setSelectedNodeId(null)
    setShowClearConfirm(false)
  }

  const newOrchestration = () => {
    setNodes([])
    setEdges([])
    setOrchId(null)
    setOrchName('My Orchestration')
    setRunLog([])
    setSelectedNodeId(null)
    setViewingOutputNodeId(null)
    setTask('')
    setShowRunPanel(false)
  }

  const cancelRun = () => {
    abortRef.current?.abort()
  }

  const processSSEEvent = useCallback((event: RunLog) => {
    setRunLog(log => [...log, event])
    if (event.type === 'start' && event.nodeId) {
      setNodes(nds => nds.map(n =>
        n.id === event.nodeId ? { ...n, data: { ...n.data, status: 'running' } } : n
      ))
    }
    if (event.type === 'done' && event.nodeId) {
      setNodes(nds => nds.map(n =>
        n.id === event.nodeId ? { ...n, data: { ...n.data, status: 'done', output: event.output } } : n
      ))
    }
    if (event.type === 'error' && event.nodeId) {
      setNodes(nds => nds.map(n =>
        n.id === event.nodeId ? { ...n, data: { ...n.data, status: 'error' } } : n
      ))
    }
  }, [setNodes])

  const handleRun = async () => {
    if (!task.trim()) { toast('error', 'Enter a task before running'); return }
    if (nodes.length === 0) { toast('error', 'Add at least one node to the canvas'); return }

    // Validate disconnected nodes
    if (nodes.length > 1) {
      const connectedIds = new Set<string>()
      for (const e of edges) { connectedIds.add(e.source); connectedIds.add(e.target) }
      const disconnected = nodes.filter(n => !connectedIds.has(n.id))
      if (disconnected.length > 0) {
        const names = disconnected.map(n => (n.data as AgentNodeData).label).join(', ')
        toast('error', `Disconnected nodes: ${names}. Connect all nodes before running.`)
        return
      }
    }

    setRunning(true)
    setRunLog([])
    setShowRunPanel(true)
    setSelectedNodeId(null)
    setViewingOutputNodeId(null)
    sseBufferRef.current = ''
    abortRef.current = new AbortController()

    // Reset node statuses
    setNodes(nds => nds.map(n => ({ ...n, data: { ...n.data, status: 'idle', output: undefined } })))

    try {
      const response = await fetch('/api/orchestrations/run', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ nodes, edges, task }),
        signal: abortRef.current.signal,
      })

      if (!response.body) throw new Error('No response body')
      const reader = response.body.getReader()
      const decoder = new TextDecoder()

      while (true) {
        const { done, value } = await reader.read()
        if (done) break

        sseBufferRef.current += decoder.decode(value, { stream: true })
        const parts = sseBufferRef.current.split('\n')
        sseBufferRef.current = parts.pop() ?? ''

        for (const line of parts) {
          const trimmed = line.trim()
          if (!trimmed.startsWith('data: ')) continue
          try {
            const event = JSON.parse(trimmed.slice(6))
            processSSEEvent(event)
          } catch {}
        }
      }

      // Flush any remaining buffer — handle multiple events
      const remaining = sseBufferRef.current.trim()
      if (remaining) {
        for (const line of remaining.split('\n')) {
          const trimmed = line.trim()
          if (!trimmed.startsWith('data: ')) continue
          try {
            const event = JSON.parse(trimmed.slice(6))
            processSSEEvent(event)
          } catch {}
        }
      }
    } catch (err: unknown) {
      if (err instanceof Error && err.name === 'AbortError') {
        setRunLog(log => [...log, { type: 'error', nodeId: null, label: null, error: 'Run cancelled' }])
      } else {
        setRunLog(log => [...log, { type: 'error', nodeId: null, label: null, error: String(err) }])
      }
    } finally {
      setRunning(false)
      abortRef.current = null
      sseBufferRef.current = ''
    }
  }

  const finalOutput = runLog.find(l => l.type === 'complete')?.finalOutput || ''

  const copyToClipboard = (text: string) => {
    navigator.clipboard.writeText(text).then(() => toast('success', 'Copied to clipboard'))
  }

  // Right panel: NodeEditPanel shows when a node is selected and run panel is NOT open
  const showNodeEdit = !!selectedNode && !showRunPanel

  const resetRunState = () => {
    setRunLog([])
    setNodes(nds => nds.map(n => ({ ...n, data: { ...n.data, status: 'idle', output: undefined } })))
  }

  return (
    <div className="flex h-screen overflow-hidden">
      {/* Left Palette */}
      <div className="w-[220px] min-w-[220px] bg-surface border-r border-border flex flex-col">
        <div className="px-4 py-4 border-b border-border">
          <h2 className="text-[13px] font-semibold flex items-center gap-2">
            <Sparkles className="w-4 h-4 text-purple" />
            Agent Palette
          </h2>
          <p className="text-[10px] text-text-muted mt-0.5">Click to add to canvas</p>
        </div>

        <div className="flex-1 overflow-y-auto py-3 px-3 space-y-1">
          {/* Custom step */}
          <button
            onClick={addCustomNode}
            className="w-full flex items-center gap-2.5 px-3 py-2 rounded-lg bg-amber-muted text-amber hover:opacity-80 transition-colors text-[12px] font-medium"
          >
            <Terminal className="w-3.5 h-3.5 shrink-0" />
            + Custom Step
          </button>

          <div className="pt-2 pb-1">
            <p className="text-[10px] uppercase tracking-wider text-text-muted font-semibold px-1">Your Agents</p>
          </div>

          {(!allAgents || allAgents.length === 0) && (
            <p className="text-[11px] text-text-muted px-1">No agents found</p>
          )}

          {allAgents?.map(agent => (
            <button
              key={`${agent.scopeLabel}-${agent.name}`}
              onClick={() => addAgentNode(agent)}
              className="w-full flex items-start gap-2 px-3 py-2 rounded-lg hover:bg-surface-2 transition-colors text-left"
            >
              <AgentIcon name={agent.name} uid={`pal-${agent.scopeLabel}-${agent.name}`} size={24} global={agent.scopeLabel === 'Global'} className="mt-0.5" />
              <div className="min-w-0">
                <p className="text-[11px] font-medium truncate">{agent.name}</p>
                <p className="text-[10px] text-text-muted">{agent.scopeLabel}</p>
              </div>
            </button>
          ))}
        </div>

        {/* Templates + Saved */}
        <div className="border-t border-border p-3 space-y-1.5">
          <button
            onClick={() => setShowTemplates(!showTemplates)}
            className="w-full flex items-center gap-2 px-3 py-2 rounded-lg hover:bg-surface-2 transition-colors text-[12px] text-text-secondary"
          >
            <LayoutTemplate className="w-3.5 h-3.5" />
            Templates
          </button>
          <button
            onClick={() => { setShowSaved(!showSaved); loadSaved() }}
            className="w-full flex items-center gap-2 px-3 py-2 rounded-lg hover:bg-surface-2 transition-colors text-[12px] text-text-secondary"
          >
            <FileText className="w-3.5 h-3.5" />
            Saved ({savedList.length})
          </button>
        </div>
      </div>

      {/* Canvas Area */}
      <div className="flex-1 flex flex-col min-w-0">
        {/* Toolbar */}
        <div className="flex items-center justify-between px-5 py-3 border-b border-border bg-surface shrink-0">
          <div className="flex items-center gap-3">
            <input
              value={orchName}
              onChange={e => setOrchName(e.target.value)}
              className="text-[15px] font-semibold bg-transparent border-none outline-none focus:ring-0 text-text w-56"
            />
            <span className="text-text-muted text-xs">{nodes.length} nodes · {edges.length} edges</span>
          </div>
          <div className="flex items-center gap-2">
            <button
              onClick={() => setShowGuide(true)}
              className="p-2 rounded-lg text-text-muted hover:text-accent hover:bg-accent-muted transition-colors"
              title="How it works"
            >
              <HelpCircle className="w-4 h-4" />
            </button>
            <button
              onClick={newOrchestration}
              className="flex items-center gap-2 px-3 py-1.5 text-sm font-medium rounded-lg border border-border hover:bg-surface-2 transition-colors"
              title="New orchestration"
            >
              <Plus className="w-3.5 h-3.5" />
              New
            </button>
            <button
              onClick={() => setShowClearConfirm(true)}
              disabled={nodes.length === 0}
              className="p-2 rounded-lg text-text-muted hover:text-red hover:bg-red-muted transition-colors disabled:opacity-30 disabled:cursor-not-allowed"
              title="Clear canvas"
            >
              <Trash2 className="w-4 h-4" />
            </button>
            <button
              onClick={handleSave}
              disabled={nodes.length === 0 || saving}
              className="flex items-center gap-2 px-3 py-1.5 text-sm font-medium rounded-lg border border-border hover:bg-surface-2 transition-colors disabled:opacity-40 disabled:cursor-not-allowed"
            >
              <Save className="w-3.5 h-3.5" />
              {saving ? 'Saving...' : 'Save'}
            </button>
            <button
              onClick={() => {
                if (running) { setShowRunPanel(true); return }
                if (!showRunPanel) { setShowRunPanel(true); return }
                if (task.trim()) { handleRun(); return }
              }}
              disabled={nodes.length === 0}
              className="flex items-center gap-2 px-4 py-1.5 text-sm font-medium rounded-lg bg-accent text-white hover:bg-accent-hover transition-colors disabled:opacity-40 disabled:cursor-not-allowed"
            >
              {running ? (
                <><Loader className="w-3.5 h-3.5 animate-spin" /> Running...</>
              ) : showRunPanel && task.trim() ? (
                <><Play className="w-3.5 h-3.5" /> Run Now</>
              ) : (
                <><Play className="w-3.5 h-3.5" /> Run</>
              )}
            </button>
          </div>
        </div>

        <div className="flex-1 flex min-h-0">
          {/* Flow Canvas */}
          <div className="flex-1 min-w-0">
            {nodes.length === 0 ? (
              <div className="h-full flex flex-col items-center justify-center text-center p-8">
                <div className="w-16 h-16 rounded-2xl bg-purple-muted flex items-center justify-center mb-4">
                  <Sparkles className="w-8 h-8 text-purple" />
                </div>
                <p className="text-base font-semibold mb-2">Agent Orchestration</p>
                <p className="text-text-muted text-sm mb-6 max-w-sm">
                  Build multi-agent pipelines by chaining your Claude agents together. Each agent processes the output of the previous one.
                </p>
                <div className="flex gap-3">
                  <button
                    onClick={() => setShowTemplates(true)}
                    className="flex items-center gap-2 px-4 py-2 bg-accent text-white rounded-lg text-sm font-medium hover:bg-accent-hover transition-colors"
                  >
                    <LayoutTemplate className="w-4 h-4" />
                    Use Template
                  </button>
                  <button
                    onClick={addCustomNode}
                    className="flex items-center gap-2 px-4 py-2 border border-border rounded-lg text-sm font-medium hover:bg-surface-2 transition-colors"
                  >
                    <Plus className="w-4 h-4" />
                    Blank Canvas
                  </button>
                </div>
                <button
                  onClick={() => setShowGuide(true)}
                  className="mt-4 flex items-center gap-1.5 text-xs text-text-muted hover:text-accent transition-colors"
                >
                  <HelpCircle className="w-3.5 h-3.5" />
                  How does orchestration work?
                </button>
              </div>
            ) : (
              <ReactFlow
                nodes={nodesWithOrder}
                edges={edges}
                onNodesChange={onNodesChange}
                onEdgesChange={onEdgesChange}
                onConnect={onConnect}
                onNodeClick={onNodeClick}
                onPaneClick={onPaneClick}
                nodeTypes={nodeTypes}
                deleteKeyCode={["Backspace", "Delete"]}
                onInit={(instance) => {
                  rfInstanceRef.current = instance
                  instance.fitView({ padding: 0.15 })
                }}
                proOptions={{ hideAttribution: true }}
                className="bg-[#0d0d0f]"
              >
                <Background variant={BackgroundVariant.Dots} gap={20} size={1} color="#2a2a2e" />
                <Controls className="!bg-surface !border-border" />
                <MiniMap
                  className="!bg-surface !border-border"
                  nodeColor="#7c3aed"
                  maskColor="rgba(0,0,0,0.4)"
                />
              </ReactFlow>
            )}
          </div>

          {/* Node Edit Panel */}
          {showNodeEdit && selectedNode && (
            <div className="w-[300px] min-w-[300px] border-l border-border bg-surface flex flex-col">
              <div className="flex items-center justify-between px-4 py-3 border-b border-border shrink-0">
                <p className="text-sm font-semibold flex items-center gap-2">
                  <Settings2 className="w-4 h-4 text-accent" />
                  Edit Node
                </p>
                <button onClick={() => setSelectedNodeId(null)} className="p-1 rounded text-text-muted hover:text-text">
                  <X className="w-4 h-4" />
                </button>
              </div>

              <div className="flex-1 overflow-y-auto px-4 py-4 space-y-4">
                <div>
                  <label className="text-xs font-medium text-text-muted block mb-1.5">Label</label>
                  <input
                    value={(selectedNode.data as AgentNodeData).label ?? ''}
                    onChange={e => updateSelectedNodeData({ label: e.target.value })}
                    className="w-full bg-surface-2 border border-border rounded-lg px-3 py-2 text-sm text-text focus:outline-none focus:border-accent/50 transition-colors"
                    placeholder="Node label"
                  />
                </div>

                <div>
                  <label className="text-xs font-medium text-text-muted block mb-1.5">Description</label>
                  <input
                    value={(selectedNode.data as AgentNodeData).description ?? ''}
                    onChange={e => updateSelectedNodeData({ description: e.target.value })}
                    className="w-full bg-surface-2 border border-border rounded-lg px-3 py-2 text-sm text-text focus:outline-none focus:border-accent/50 transition-colors"
                    placeholder="Short description"
                  />
                </div>

                {/* Instructions — shown for custom nodes and agent nodes */}
                <div>
                  <label className="text-xs font-medium text-text-muted block mb-1.5">
                    Instructions
                    <span className="ml-1.5 text-[10px] text-text-muted font-normal">(overrides agent default)</span>
                  </label>
                  <textarea
                    value={(selectedNode.data as AgentNodeData).instructions ?? ''}
                    onChange={e => updateSelectedNodeData({ instructions: e.target.value })}
                    rows={8}
                    className="w-full bg-surface-2 border border-border rounded-lg px-3 py-2.5 text-sm text-text resize-none focus:outline-none focus:border-accent/50 transition-colors placeholder:text-text-muted"
                    placeholder="Describe what this step should do. Leave empty to use the agent's built-in instructions."
                  />
                </div>

                <div className="pt-2 border-t border-border">
                  <div className="text-[10px] text-text-muted mb-2">Node ID: <code className="font-mono">{selectedNode.id}</code></div>
                  {(selectedNode.data as AgentNodeData).scope && (
                    <div className="text-[10px] text-text-muted">Scope: {(selectedNode.data as AgentNodeData).scope}</div>
                  )}
                </div>
              </div>

              <div className="px-4 py-3 border-t border-border shrink-0">
                <button
                  onClick={deleteSelectedNode}
                  className="w-full flex items-center justify-center gap-2 px-3 py-2 text-sm font-medium rounded-lg border border-red/30 text-red hover:bg-red-muted transition-colors"
                >
                  <Trash2 className="w-3.5 h-3.5" />
                  Delete Node
                </button>
              </div>
            </div>
          )}

          {/* Run Panel */}
          {showRunPanel && (
            <div className="w-[340px] min-w-[340px] border-l border-border bg-surface flex flex-col">
              <div className="flex items-center justify-between px-4 py-3 border-b border-border shrink-0">
                <p className="text-sm font-semibold flex items-center gap-2">
                  <Play className="w-4 h-4 text-accent" />
                  Run Orchestration
                </p>
                <button onClick={() => setShowRunPanel(false)} className="p-1 rounded text-text-muted hover:text-text">
                  <X className="w-4 h-4" />
                </button>
              </div>

              <div className="px-4 py-4 border-b border-border shrink-0">
                <label className="text-xs font-medium text-text-muted block mb-1.5">Initial Task</label>
                <textarea
                  value={task}
                  onChange={e => setTask(e.target.value)}
                  placeholder="e.g. Build a React hook for pagination with TypeScript..."
                  rows={4}
                  className="w-full bg-surface-2 border border-border rounded-xl px-3 py-2.5 text-sm text-text resize-none focus:outline-none focus:border-accent/50 transition-colors placeholder:text-text-muted"
                />
                <div className="flex gap-2 mt-3">
                  {!running && runLog.length > 0 ? (
                    <>
                      <button
                        onClick={handleRun}
                        disabled={!task.trim() || nodes.length === 0}
                        className="flex-1 flex items-center justify-center gap-2 px-4 py-2.5 bg-accent text-white rounded-xl text-sm font-medium hover:bg-accent-hover disabled:opacity-40 disabled:cursor-not-allowed transition-colors"
                      >
                        <RotateCcw className="w-4 h-4" /> Re-run
                      </button>
                      <button
                        onClick={resetRunState}
                        className="px-3 py-2.5 border border-border rounded-xl text-sm font-medium hover:bg-surface-2 transition-colors"
                      >
                        Reset
                      </button>
                    </>
                  ) : (
                    <>
                      <button
                        onClick={handleRun}
                        disabled={!task.trim() || running || nodes.length === 0}
                        className="flex-1 flex items-center justify-center gap-2 px-4 py-2.5 bg-accent text-white rounded-xl text-sm font-medium hover:bg-accent-hover disabled:opacity-40 disabled:cursor-not-allowed transition-colors"
                      >
                        {running ? <><Loader className="w-4 h-4 animate-spin" /> Running...</> : <><Play className="w-4 h-4" /> Start Run</>}
                      </button>
                      {running && (
                        <button
                          onClick={cancelRun}
                          className="px-3 py-2.5 border border-red/40 text-red rounded-xl text-sm font-medium hover:bg-red-muted transition-colors"
                        >
                          Cancel
                        </button>
                      )}
                    </>
                  )}
                </div>
              </div>

              {/* Log */}
              <div className="flex-1 overflow-y-auto px-4 py-3 space-y-2">
                {runLog.length === 0 && (
                  <p className="text-xs text-text-muted text-center py-6">Run log will appear here…</p>
                )}
                {runLog.map((log, i) => (
                  <div key={i} className={`rounded-xl px-3 py-2.5 text-[12px] ${
                    log.type === 'start' ? 'bg-purple-muted border border-purple/20' :
                    log.type === 'done' ? 'bg-green-muted border border-green/20' :
                    log.type === 'error' ? 'bg-red-muted border border-red/20' :
                    'bg-accent-muted border border-accent/20'
                  }`}>
                    <div className="flex items-center gap-1.5 font-medium mb-1">
                      {log.type === 'start' && <><Loader className="w-3 h-3 animate-spin text-purple" /><span className="text-purple">{log.label} — running</span></>}
                      {log.type === 'done' && <><CheckCircle className="w-3 h-3 text-green" /><span className="text-green">{log.label} — done</span></>}
                      {log.type === 'error' && <><AlertCircle className="w-3 h-3 text-red" /><span className="text-red">{log.label || 'Error'}</span></>}
                      {log.type === 'complete' && <><Sparkles className="w-3 h-3 text-accent" /><span className="text-accent">Orchestration complete</span></>}
                    </div>
                    {log.output && (
                      <>
                        <p className="text-text-secondary leading-snug line-clamp-4">{log.output}</p>
                        {log.nodeId && (
                          <button
                            onClick={() => setViewingOutputNodeId(log.nodeId)}
                            className="text-[10px] text-accent hover:underline mt-1"
                          >
                            View full output
                          </button>
                        )}
                      </>
                    )}
                    {log.error && <p className="text-red leading-snug">{log.error}</p>}
                  </div>
                ))}

                {finalOutput && (
                  <div className="mt-2 rounded-xl bg-surface-2 border border-border p-3">
                    <div className="flex items-center justify-between mb-2">
                      <p className="text-[11px] font-semibold text-text-muted">Final Output</p>
                      <button
                        onClick={() => copyToClipboard(finalOutput)}
                        className="flex items-center gap-1 text-[10px] text-text-muted hover:text-text transition-colors px-1.5 py-0.5 rounded hover:bg-surface"
                      >
                        <Copy className="w-3 h-3" />
                        Copy
                      </button>
                    </div>
                    <pre className="text-[11px] text-text whitespace-pre-wrap leading-relaxed">{finalOutput}</pre>
                  </div>
                )}

                <div ref={logEndRef} />
              </div>
            </div>
          )}
        </div>
      </div>

      {/* Clear Confirm Modal */}
      {showClearConfirm && (
        <div className="fixed inset-0 z-50 flex items-center justify-center">
          <div className="absolute inset-0 bg-black/40" onClick={() => setShowClearConfirm(false)} />
          <div className="relative bg-surface border border-border rounded-2xl p-6 w-[360px] shadow-2xl">
            <h3 className="text-base font-semibold mb-2">Clear canvas?</h3>
            <p className="text-sm text-text-muted mb-5">This will remove all {nodes.length} nodes and {edges.length} edges. This cannot be undone.</p>
            <div className="flex gap-3 justify-end">
              <button
                onClick={() => setShowClearConfirm(false)}
                className="px-4 py-2 text-sm rounded-lg border border-border hover:bg-surface-2 transition-colors"
              >
                Cancel
              </button>
              <button
                onClick={clearCanvas}
                className="px-4 py-2 text-sm rounded-lg bg-red text-white hover:opacity-90 transition-opacity font-medium"
              >
                Clear
              </button>
            </div>
          </div>
        </div>
      )}

      {/* Templates Modal */}
      {showTemplates && (
        <div className="fixed inset-0 z-50 flex items-center justify-center">
          <div className="absolute inset-0 bg-black/40" onClick={() => setShowTemplates(false)} />
          <div className="relative bg-surface border border-border rounded-2xl p-6 w-[500px] shadow-2xl">
            <div className="flex items-center justify-between mb-4">
              <h3 className="text-base font-semibold">Pipeline Templates</h3>
              <button onClick={() => setShowTemplates(false)} className="p-1.5 rounded-lg hover:bg-surface-2 text-text-muted">
                <X className="w-4 h-4" />
              </button>
            </div>
            <div className="space-y-3">
              {TEMPLATES.map(tpl => (
                <button
                  key={tpl.name}
                  onClick={() => loadTemplate(tpl)}
                  className="w-full flex items-start gap-4 p-4 rounded-xl border border-border hover:border-accent/30 hover:bg-accent-muted text-left transition-all group"
                >
                  <div className="w-10 h-10 rounded-xl bg-purple-muted flex items-center justify-center shrink-0">
                    <Sparkles className="w-5 h-5 text-purple" />
                  </div>
                  <div>
                    <p className="text-sm font-semibold group-hover:text-accent-hover transition-colors">{tpl.name}</p>
                    <p className="text-xs text-text-muted mt-0.5">{tpl.description} · {tpl.nodes.length} nodes</p>
                  </div>
                  <ChevronRight className="w-4 h-4 text-text-muted ml-auto mt-1 shrink-0" />
                </button>
              ))}
            </div>
          </div>
        </div>
      )}

      {/* Saved Orchestrations Modal */}
      {showSaved && (
        <div className="fixed inset-0 z-50 flex items-center justify-center">
          <div className="absolute inset-0 bg-black/40" onClick={() => setShowSaved(false)} />
          <div className="relative bg-surface border border-border rounded-2xl p-6 w-[460px] shadow-2xl">
            <div className="flex items-center justify-between mb-4">
              <h3 className="text-base font-semibold">Saved Orchestrations</h3>
              <button onClick={() => setShowSaved(false)} className="p-1.5 rounded-lg hover:bg-surface-2 text-text-muted">
                <X className="w-4 h-4" />
              </button>
            </div>
            {savedList.length === 0 ? (
              <p className="text-sm text-text-muted text-center py-6">No saved orchestrations yet.</p>
            ) : (
              <div className="space-y-2">
                {savedList.map(o => (
                  <div key={o.id} className="flex items-center gap-3 px-3 py-2.5 rounded-xl border border-border hover:border-accent/20 group">
                    <div className="w-8 h-8 rounded-lg bg-purple-muted flex items-center justify-center shrink-0">
                      <Sparkles className="w-4 h-4 text-purple" />
                    </div>
                    <div className="flex-1 min-w-0">
                      <p className="text-sm font-medium truncate">{o.name}</p>
                      <p className="text-[10px] text-text-muted">{(o as { nodes?: unknown[] }).nodes?.length ?? '?'} nodes · {new Date(o.updatedAt).toLocaleDateString()}</p>
                    </div>
                    <button onClick={() => handleLoad(o.id)} className="text-xs text-accent hover:underline">Load</button>
                    <button onClick={() => handleDelete(o.id)} className="p-1 text-text-muted hover:text-red opacity-0 group-hover:opacity-100 transition-all">
                      <Trash2 className="w-3.5 h-3.5" />
                    </button>
                  </div>
                ))}
              </div>
            )}
          </div>
        </div>
      )}

      {/* Output Viewer Modal */}
      {viewingOutputNodeId && viewingNode && (
        <div className="fixed inset-0 z-50 flex items-center justify-center">
          <div className="absolute inset-0 bg-black/40" onClick={() => setViewingOutputNodeId(null)} />
          <div className="relative bg-surface border border-border rounded-2xl w-[640px] max-h-[80vh] shadow-2xl flex flex-col">
            <div className="flex items-center justify-between px-5 py-3.5 border-b border-border shrink-0">
              <div className="flex items-center gap-2">
                {(viewingNode.data as AgentNodeData).status === 'done' ? (
                  <CheckCircle className="w-4 h-4 text-green" />
                ) : (
                  <AlertCircle className="w-4 h-4 text-red" />
                )}
                <h3 className="text-sm font-semibold">{(viewingNode.data as AgentNodeData).label} — Output</h3>
              </div>
              <div className="flex items-center gap-2">
                {viewingOutput && (
                  <button
                    onClick={() => copyToClipboard(viewingOutput)}
                    className="flex items-center gap-1.5 text-xs text-text-muted hover:text-text px-2 py-1 rounded-lg hover:bg-surface-2"
                  >
                    <Copy className="w-3.5 h-3.5" /> Copy
                  </button>
                )}
                <button onClick={() => setViewingOutputNodeId(null)} className="p-1 rounded text-text-muted hover:text-text">
                  <X className="w-4 h-4" />
                </button>
              </div>
            </div>
            <div className="flex-1 overflow-y-auto px-5 py-4">
              {viewingOutput ? (
                <pre className="text-sm text-text whitespace-pre-wrap leading-relaxed">{viewingOutput}</pre>
              ) : (
                <p className="text-sm text-text-muted">No output available for this node.</p>
              )}
            </div>
          </div>
        </div>
      )}
    </div>
  )
}
